package me.eiakoji.wiki.poeaa.reservation.domain;

import jakarta.persistence.*;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "reservations")
public class ReservationEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private String guestEmail;

    @Column(nullable = false)
    private String roomNumber;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private ReservationStatus status;

    @Version
    @Column(name = "version", nullable = false)
    private Long version;

    @Column(nullable = false, updatable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    protected ReservationEntity() {}

    public ReservationEntity(UUID id, String guestEmail, String roomNumber) {
        this.id = id;
        this.guestEmail = guestEmail;
        this.roomNumber = roomNumber;
        this.status = ReservationStatus.PENDING;
        this.createdAt = Instant.now();
        this.updatedAt = Instant.now();
    }

    public void confirm(String guestEmail) {
        if (this.status != ReservationStatus.PENDING) {
            throw new IllegalStateException("Reservation cannot be confirmed from status: " + this.status);
        }
        this.guestEmail = guestEmail;
        this.status = ReservationStatus.CONFIRMED;
        this.updatedAt = Instant.now();
    }

    public UUID getId() { return id; }
    public String getGuestEmail() { return guestEmail; }
    public String getRoomNumber() { return roomNumber; }
    public ReservationStatus getStatus() { return status; }
    public Long getVersion() { return version; }
}

package me.eiakoji.wiki.poeaa.reservation.application;

import me.eiakoji.wiki.poeaa.reservation.domain.ReservationEntity;
import me.eiakoji.wiki.poeaa.reservation.domain.ReservationRepository;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class ReservationCheckoutService {

    private final ReservationRepository reservationRepository;

    public ReservationCheckoutService(ReservationRepository reservationRepository) {
        this.reservationRepository = reservationRepository;
    }

    @Transactional
    public CheckoutResult confirmReservation(UUID reservationId, Long expectedVersion, String guestEmail) {
        ReservationEntity reservation = reservationRepository.findById(reservationId)
                .orElseThrow(() -> new EntityNotFoundException("Reservation not found: " + reservationId));

        if (!reservation.getVersion().equals(expectedVersion)) {
            // Early detection before issuing SQL UPDATE
            return CheckoutResult.conflict(reservation.getId(), reservation.getVersion(), "Stale transaction token");
        }

        try {
            reservation.confirm(guestEmail);
            reservationRepository.save(reservation);
            return CheckoutResult.success(reservation.getId(), reservation.getVersion());
        } catch (OptimisticLockingFailureException ex) {
            // Concurrent race collided during commit
            return CheckoutResult.conflict(reservation.getId(), null, "Concurrent modification detected. Please reload.");
        }
    }
}

package me.eiakoji.wiki.poeaa.concurrency.lock;

import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Component;

import java.time.Duration;
import java.util.Collections;
import java.util.Optional;

@Component
public class RedisLockManager {

    private final StringRedisTemplate redisTemplate;
    private final DefaultRedisScript<Long> releaseScript;

    private static final String RELEASE_LUA =
            "if redis.call('get', KEYS[1]) == ARGV[1] then " +
            "    return redis.call('del', KEYS[1]) " +
            "else " +
            "    return 0 " +
            "end";

    public RedisLockManager(StringRedisTemplate redisTemplate) {
        this.redisTemplate = redisTemplate;
        this.releaseScript = new DefaultRedisScript<>(RELEASE_LUA, Long.class);
    }

    public boolean acquireLease(String resourceKey, String ownerToken, Duration ttl) {
        Boolean acquired = redisTemplate.opsForValue()
                .setIfAbsent(resourceKey, ownerToken, ttl);
        return Boolean.TRUE.equals(acquired);
    }

    public boolean renewLease(String resourceKey, String ownerToken, Duration ttl) {
        String currentOwner = redisTemplate.opsForValue().get(resourceKey);
        if (ownerToken.equals(currentOwner)) {
            return Boolean.TRUE.equals(redisTemplate.expire(resourceKey, ttl));
        }
        return false;
    }

    public boolean releaseLease(String resourceKey, String ownerToken) {
        Long result = redisTemplate.execute(
                releaseScript,
                Collections.singletonList(resourceKey),
                ownerToken
        );
        return result != null && result == 1L;
    }

    public Optional<String> getLockOwner(String resourceKey) {
        return Optional.ofNullable(redisTemplate.opsForValue().get(resourceKey));
    }
}

package me.eiakoji.wiki.poeaa.reservation.domain;

import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.Optional;
import java.util.UUID;

public interface ReservationRepository extends JpaRepository<ReservationEntity, UUID> {

    /**
     * Acquires a Coarse-Grained Lock on the Aggregate Root.
     * Forces an optimistic version increment upon commit to ensure no concurrent
     * child mutations (holds, addons, line items) can commit undetected.
     */
    @Lock(LockModeType.OPTIMISTIC_FORCE_INCREMENT)
    @Query("SELECT r FROM ReservationEntity r WHERE r.id = :id")
    Optional<ReservationEntity> findByIdWithCoarseGrainedLock(@Param("id") UUID id);
}

package me.eiakoji.wiki.poeaa.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.serializer.GenericJackson2JsonRedisSerializer;
import org.springframework.data.redis.serializer.StringRedisSerializer;
import org.springframework.session.data.redis.config.annotation.web.http.EnableRedisHttpSession;

@Configuration
@EnableRedisHttpSession(maxInactiveIntervalInSeconds = 1800) // 30-minute session TTL
public class SessionConfiguration {

    @Bean
    public RedisTemplate<String, Object> sessionRedisTemplate(RedisConnectionFactory connectionFactory) {
        RedisTemplate<String, Object> template = new RedisTemplate<>();
        template.setConnectionFactory(connectionFactory);
        template.setKeySerializer(new StringRedisSerializer());
        template.setValueSerializer(new GenericJackson2JsonRedisSerializer());
        template.setHashKeySerializer(new StringRedisSerializer());
        template.setHashValueSerializer(new GenericJackson2JsonRedisSerializer());
        template.afterPropertiesSet();
        return template;
    }
}

