package me.eiakoji.wiki.poeaa.gateway.infrastructure;

import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import me.eiakoji.wiki.poeaa.gateway.PaymentAuthorization;
import me.eiakoji.wiki.poeaa.gateway.PaymentGateway;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

import java.math.BigDecimal;
import java.time.Duration;
import java.util.Map;
import java.util.UUID;

@Component
@ConditionalOnProperty(name = "payment.provider", havingValue = "stripe", matchIfMissing = true)
public class StripePaymentGateway implements PaymentGateway {

    private static final Logger log = LoggerFactory.getLogger(StripePaymentGateway.class);
    private final RestClient restClient;

    public StripePaymentGateway(RestClient.Builder restClientBuilder) {
        this.restClient = restClientBuilder
                .baseUrl("https://api.stripe.com/v1")
                .defaultHeader("Authorization", "Bearer " + System.getenv().getOrDefault("STRIPE_SECRET_KEY", "sk_test_mock"))
                .build();
    }

    @Override
    @CircuitBreaker(name = "paymentGateway", fallbackMethod = "fallbackAuthorization")
    public PaymentAuthorization authorizeCharge(UUID reservationId, BigDecimal amount, String currency, String paymentMethodNonce) {
        log.info("Authorizing charge of {} {} for reservation {}", amount, currency, reservationId);

        Map<?, ?> response = restClient.post()
                .uri("/payment_intents")
                .contentType(MediaType.APPLICATION_FORM_URLENCODED)
                .body("amount=" + amount.multiply(BigDecimal.valueOf(100)).intValue() +
                      "&currency=" + currency.toLowerCase() +
                      "&payment_method=" + paymentMethodNonce +
                      "&confirm=true")
                .retrieve()
                .body(Map.class);

        String intentId = (String) response.get("id");
        String status = (String) response.get("status");

        return new PaymentAuthorization(intentId, "succeeded".equals(status), status);
    }

    public PaymentAuthorization fallbackAuthorization(UUID reservationId, BigDecimal amount, String currency, String nonce, Throwable t) {
        log.error("Payment gateway failure for reservation {}: {}", reservationId, t.getMessage());
        return new PaymentAuthorization("FALLBACK-" + UUID.randomUUID(), false, "SERVICE_UNAVAILABLE");
    }
}

