package me.eiakoji.wiki.poeaa.pricing;

import java.math.BigDecimal;

public sealed interface DiscountPolicy permits StandardMemberDiscount, ZeroDiscountPolicy {

    BigDecimal applyDiscount(BigDecimal baseRate);

    static DiscountPolicy zero() {
        return new ZeroDiscountPolicy();
    }
}

final class ZeroDiscountPolicy implements DiscountPolicy {
    @Override
    public BigDecimal applyDiscount(BigDecimal baseRate) {
        return baseRate; // No-op: returns original rate with zero branching
    }
}

package me.eiakoji.wiki.poeaa.reservation.application;

import me.eiakoji.wiki.poeaa.concurrency.lock.RedisLockManager;
import me.eiakoji.wiki.poeaa.gateway.PaymentAuthorization;
import me.eiakoji.wiki.poeaa.gateway.PaymentGateway;
import me.eiakoji.wiki.poeaa.reservation.domain.ReservationEntity;
import me.eiakoji.wiki.poeaa.reservation.domain.ReservationRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.Duration;
import java.util.UUID;

@Service
public class HotelReservationOrchestrator {

    private static final Logger log = LoggerFactory.getLogger(HotelReservationOrchestrator.class);
    private static final Duration HOLD_TTL = Duration.ofMinutes(10);

    private final RedisLockManager lockManager;
    private final ReservationRepository reservationRepository;
    private final PaymentGateway paymentGateway;

    public HotelReservationOrchestrator(
            RedisLockManager lockManager,
            ReservationRepository reservationRepository,
            PaymentGateway paymentGateway
    ) {
        this.lockManager = lockManager;
        this.reservationRepository = reservationRepository;
        this.paymentGateway = paymentGateway;
    }

    /**
     * Step 2: Acquire Pessimistic Offline Lease in Redis during user think-time.
     */
    public boolean holdRoom(String roomNumber, String sessionToken) {
        String lockKey = "lock:room:" + roomNumber;
        boolean acquired = lockManager.acquireLease(lockKey, sessionToken, HOLD_TTL);
        if (acquired) {
            log.info("Acquired 10-minute hold on room {} for session {}", roomNumber, sessionToken);
        }
        return acquired;
    }

    /**
     * Step 4: Final atomic commit within a short-lived ACID transaction.
     */
    @Transactional
    public BookingConfirmation commitBooking(
            UUID reservationId,
            String roomNumber,
            String sessionToken,
            Long expectedVersion,
            BigDecimal chargeAmount,
            String paymentNonce
    ) {
        String lockKey = "lock:room:" + roomNumber;

        // 1. Verify Pessimistic Lease ownership
        String currentHolder = lockManager.getLockOwner(lockKey).orElse(null);
        if (!sessionToken.equals(currentHolder)) {
            throw new IllegalStateException("Room hold expired or owned by another session. Booking rejected.");
        }

        // 2. Load Aggregate Root with Coarse-Grained Lock (OPTIMISTIC_FORCE_INCREMENT)
        ReservationEntity reservation = reservationRepository.findByIdWithCoarseGrainedLock(reservationId)
                .orElseThrow(() -> new EntityNotFoundException("Reservation not found: " + reservationId));

        if (!reservation.getVersion().equals(expectedVersion)) {
            throw new ConcurrentModificationException("Reservation modified by another actor. Please reload.");
        }

        // 3. Execute external payment via Resilient Gateway
        PaymentAuthorization authorization = paymentGateway.authorizeCharge(
                reservationId,
                chargeAmount,
                "USD",
                paymentNonce
        );

        if (!authorization.isAuthorized()) {
            throw new PaymentFailedException("Payment authorization failed: " + authorization.status());
        }

        // 4. Update domain aggregate state
        reservation.confirm(sessionToken);
        reservationRepository.save(reservation);

        // 5. Release Pessimistic Lease
        lockManager.releaseLease(lockKey, sessionToken);
        log.info("Booking confirmed and lease released for reservation {}", reservationId);

        return new BookingConfirmation(reservation.getId(), authorization.transactionId(), "CONFIRMED");
    }
}
